def correct_order(
    tenant: str,
    request_id: str,
    order_id: str,
    new_order_id: str,
    new_amount_cents: int,
    new_currency: str,
) -> IdemResult:
    request_hash = _fingerprint((SCOPE_CORRECTION, order_id, new_order_id, new_amount_cents, new_currency))
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = idempotency.get_conn(conn, tenant, request_id)
        if existing is not None:
            _finish(conn)
            if existing["scope"] != SCOPE_CORRECTION or existing["request_hash"] != request_hash:
                raise IdempotentConflict("request id was already used with different request content")
            return IdemResult(existing["status_code"], json.loads(existing["response_json"]), replay=True)

        try:
            try:
                body = orders.correct_conn(
                    conn, tenant, order_id, new_order_id, new_amount_cents, new_currency, request_id
                )
                status_code = 200
            except LookupError:
                status_code, body = 404, {"detail": "order not found"}
            except ValueError as error:
                # 含 CorrectionRejected：业务拒绝结论已随更正留痕落库，此处只固化响应
                status_code, body = 409, {"detail": str(error)}
            idempotency.insert_conn(
                conn, tenant, request_id, SCOPE_CORRECTION, request_hash, order_id,
                status_code, json.dumps(body, ensure_ascii=False),
            )
            _finish(conn)
        except Exception:
            _abort(conn)
            raise
    finally:
        conn.close()
    return IdemResult(status_code, body, replay=False)

import os
import tempfile

os.environ.setdefault("APP_DB", os.path.join(tempfile.mkdtemp(), "test.sqlite"))
from fastapi.testclient import TestClient

from app.entry import app
from app.store.db import migrate

migrate()
client = TestClient(app)

def test_accept_and_read_order() -> None:
    body = {"tenant": "t1", "order_id": "o1", "amount_cents": 500, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    got = client.get("/orders/o1", headers={"X-Tenant": "t1"})
    assert got.status_code == 200 and got.json()["outstanding_cents"] == 500

def test_duplicate_is_refused() -> None:
    body = {"tenant": "t1", "order_id": "o2", "amount_cents": 100, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    assert client.post("/orders", json=body).status_code == 409

def test_cross_tenant_read_is_not_found() -> None:
    body = {"tenant": "t1", "order_id": "o3", "amount_cents": 100, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.get("/orders/o3", headers={"X-Tenant": "t2"}).status_code == 404

def test_payment_cannot_exceed_outstanding() -> None:
    body = {"tenant": "t1", "order_id": "o4", "amount_cents": 300, "currency": "CNY"}
